// src/App.js - Con flujo de configuración inicial obligatoria
import React, { useState, useEffect } from 'react';
import {
  Card,
  Typography,
  Grid,
  Slider,
  Button,
  Alert,
  CircularProgress,
  Box,
  Divider,
  Chip,
  LinearProgress,
  TextField,
  InputAdornment,
  IconButton,
  Drawer,
  List,
  ListItem,
  ListItemText,
  ListItemIcon,
  AppBar,
  Toolbar,
  Container,
  Stepper,
  Step,
  StepLabel
} from '@mui/material';
import {
  ResponsiveContainer,
  AreaChart,
  Area,
  CartesianGrid,
  XAxis,
  YAxis,
  Tooltip as RechartsTooltip
} from 'recharts';
import { io } from 'socket.io-client';
import MenuIcon from '@mui/icons-material/Menu';
import DashboardIcon from '@mui/icons-material/Dashboard';
import SettingsIcon from '@mui/icons-material/Settings';
import DeviceHubIcon from '@mui/icons-material/DeviceHub';
import LogoutIcon from '@mui/icons-material/Logout';
import AddIcon from '@mui/icons-material/Add';
import SaveIcon from '@mui/icons-material/Save';
import { useAuth } from './context/AuthContext';
import Auth from './components/Auth';
import axios from 'axios';

const API_URL = 'https://backend-control-tanque-production-154a.up.railway.app';

const COLORS = {
  primary: '#2563eb',
  success: '#10b981',
  warning: '#f59e0b',
  danger: '#ef4444',
  dark: '#1f2937',
  light: '#f3f4f6'
};

function App() {
  const { user, logout, isAuthenticated, loading } = useAuth();
  const [devices, setDevices] = useState([]);
  const [selectedDevice, setSelectedDevice] = useState(null);
  const [history, setHistory] = useState([]);
  const [socket, setSocket] = useState(null);
  const [drawerOpen, setDrawerOpen] = useState(false);
  const [alert, setAlert] = useState(null);
  const [showConfig, setShowConfig] = useState(false);
  const [activeStep, setActiveStep] = useState(0);
  const [configCompleted, setConfigCompleted] = useState(false);
  const [isConfiguring, setIsConfiguring] = useState(false);
  
  // Configuración del dispositivo
  const [tankHeight, setTankHeight] = useState('');
  const [minLevel, setMinLevel] = useState('');
  const [maxLevel, setMaxLevel] = useState('');

  useEffect(() => {
    if (isAuthenticated) {
      fetchDevices();
    }
  }, [isAuthenticated]);

  useEffect(() => {
    if (selectedDevice && isAuthenticated && !showConfig && !configCompleted) {
      if (selectedDevice.tankHeight && selectedDevice.minLevel && selectedDevice.maxLevel) {
        setConfigCompleted(true);
        setShowConfig(false);
      } else {
        setShowConfig(true);
        setActiveStep(0);
        setTankHeight(selectedDevice.tankHeight?.toString() || '100');
        setMinLevel(selectedDevice.minLevel?.toString() || '20');
        setMaxLevel(selectedDevice.maxLevel?.toString() || '80');
      }
    }
  }, [selectedDevice]);

  useEffect(() => {
    if (selectedDevice && isAuthenticated && configCompleted) {
      fetchDeviceStatus(selectedDevice.deviceId);
      fetchDeviceHistory(selectedDevice.deviceId);
      connectWebSocket(selectedDevice.deviceId);
    }
  }, [selectedDevice, configCompleted]);

  const fetchDevices = async () => {
    try {
      const response = await axios.get(`${API_URL}/api/devices`);
      setDevices(response.data);
      if (response.data.length > 0 && !selectedDevice) {
        setSelectedDevice(response.data[0]);
      }
    } catch (error) {
      console.error('Error cargando dispositivos:', error);
    }
  };

  const fetchDeviceStatus = async (deviceId) => {
    try {
      const response = await axios.get(`${API_URL}/api/status/${deviceId}`);
      setSelectedDevice(prev => ({ ...prev, currentStatus: response.data }));
    } catch (error) {
      console.error('Error cargando estado:', error);
    }
  };

  const fetchDeviceHistory = async (deviceId) => {
    try {
      const response = await axios.get(`${API_URL}/api/history/${deviceId}`);
      setHistory(response.data);
    } catch (error) {
      console.error('Error cargando historial:', error);
    }
  };

  const connectWebSocket = (deviceId) => {
    if (socket) socket.close();
    const newSocket = io(API_URL);
    newSocket.on(`status_update_${deviceId}`, (data) => {
      setSelectedDevice(prev => ({ ...prev, currentStatus: data }));
    });
    setSocket(newSocket);
    return () => newSocket.close();
  };

  const saveDeviceConfig = async () => {
    if (!selectedDevice) return;
    
    const heightVal = parseInt(tankHeight);
    const minVal = parseInt(minLevel);
    const maxVal = parseInt(maxLevel);

    if (isNaN(heightVal) || heightVal <= 0 || heightVal > 500) {
      setAlert({ type: 'error', message: 'La altura debe ser entre 1 y 500 cm' });
      return;
    }
    if (isNaN(minVal) || minVal < 0 || minVal > 100) {
      setAlert({ type: 'error', message: 'El nivel mínimo debe ser entre 0 y 100%' });
      return;
    }
    if (isNaN(maxVal) || maxVal < 0 || maxVal > 100) {
      setAlert({ type: 'error', message: 'El nivel máximo debe ser entre 0 y 100%' });
      return;
    }
    if (minVal >= maxVal) {
      setAlert({ type: 'error', message: 'El nivel mínimo debe ser menor que el máximo' });
      return;
    }

    setIsConfiguring(true);

    try {
      await axios.post(`${API_URL}/api/config`, {
        deviceId: selectedDevice.deviceId,
        minLevel: minVal,
        maxLevel: maxVal,
        tankHeight: heightVal
      });
      
      setAlert({ type: 'success', message: '✅ Configuración guardada correctamente' });
      
      setSelectedDevice(prev => ({ 
        ...prev, 
        tankHeight: heightVal, 
        minLevel: minVal, 
        maxLevel: maxVal
      }));
      
      setConfigCompleted(true);
      setShowConfig(false);
      setActiveStep(1);
      
      setTimeout(() => setAlert(null), 3000);
    } catch (error) {
      setAlert({ type: 'error', message: 'Error al guardar configuración' });
    } finally {
      setIsConfiguring(false);
    }
  };

  if (loading) {
    return (
      <Box display="flex" justifyContent="center" alignItems="center" minHeight="100vh">
        <CircularProgress size={60} />
      </Box>
    );
  }

  if (!isAuthenticated) {
    return <Auth />;
  }

  // Pantalla de configuración inicial (si no hay dispositivos o no están configurados)
  if ((!selectedDevice && devices.length === 0) || (selectedDevice && !configCompleted && showConfig)) {
    return (
      <Box sx={{ minHeight: '100vh', bgcolor: COLORS.light, py: 4 }}>
        <Container maxWidth="md">
          <Card sx={{ p: 4 }}>
            <Box textAlign="center" mb={4}>
              <Typography variant="h4" gutterBottom>
                ⚙️ Configuración del Tanque
              </Typography>
              <Typography variant="body2" color="textSecondary">
                {selectedDevice 
                  ? `Dispositivo: ${selectedDevice.name || selectedDevice.deviceId}` 
                  : 'Primero debes conectar tu ESP8266 para que aparezca el dispositivo'}
              </Typography>
            </Box>

            <Stepper activeStep={activeStep} sx={{ mb: 4 }}>
              <Step>
                <StepLabel>Configuración</StepLabel>
              </Step>
              <Step>
                <StepLabel>Dashboard</StepLabel>
              </Step>
            </Stepper>

            {!selectedDevice && devices.length === 0 && (
              <Alert severity="info" sx={{ mb: 3 }}>
                No hay dispositivos detectados. Conecta tu ESP8266 y espera a que aparezca aquí.
              </Alert>
            )}

            <Grid container spacing={3}>
              <Grid item xs={12}>
                <Typography gutterBottom>📏 Altura del Tanque (cm)</Typography>
                <TextField
                  fullWidth
                  type="number"
                  value={tankHeight}
                  onChange={(e) => setTankHeight(e.target.value)}
                  placeholder="Ej: 100"
                  InputProps={{ endAdornment: <InputAdornment position="end">cm</InputAdornment> }}
                  helperText="Mide la altura total de tu tanque en centímetros"
                />
              </Grid>

              <Grid item xs={12}>
                <Typography gutterBottom>⬇️ Nivel Mínimo (Encender bomba)</Typography>
                <TextField
                  fullWidth
                  type="number"
                  value={minLevel}
                  onChange={(e) => setMinLevel(e.target.value)}
                  placeholder="Ej: 20"
                  InputProps={{ endAdornment: <InputAdornment position="end">%</InputAdornment> }}
                  helperText="Cuando el nivel baje de este valor, la bomba se encenderá"
                />
                <Slider
                  value={parseInt(minLevel) || 0}
                  onChange={(_, val) => setMinLevel(val.toString())}
                  min={0}
                  max={100}
                  valueLabelDisplay="auto"
                  color="warning"
                  sx={{ mt: 2 }}
                />
              </Grid>

              <Grid item xs={12}>
                <Typography gutterBottom>⬆️ Nivel Máximo (Apagar bomba)</Typography>
                <TextField
                  fullWidth
                  type="number"
                  value={maxLevel}
                  onChange={(e) => setMaxLevel(e.target.value)}
                  placeholder="Ej: 80"
                  InputProps={{ endAdornment: <InputAdornment position="end">%</InputAdornment> }}
                  helperText="Cuando el nivel supere este valor, la bomba se apagará"
                />
                <Slider
                  value={parseInt(maxLevel) || 0}
                  onChange={(_, val) => setMaxLevel(val.toString())}
                  min={0}
                  max={100}
                  valueLabelDisplay="auto"
                  color="primary"
                  sx={{ mt: 2 }}
                />
              </Grid>

              <Grid item xs={12}>
                <Button
                  fullWidth
                  variant="contained"
                  size="large"
                  startIcon={<SaveIcon />}
                  onClick={saveDeviceConfig}
                  disabled={isConfiguring || !selectedDevice}
                  sx={{ py: 1.5 }}
                >
                  {isConfiguring ? 'Guardando...' : 'Guardar y continuar'}
                </Button>
              </Grid>
            </Grid>
          </Card>
        </Container>
      </Box>
    );
  }

  // Dashboard principal (después de la configuración)
  if (!selectedDevice) {
    return (
      <Container maxWidth="sm" sx={{ mt: 8 }}>
        <Card sx={{ p: 4, textAlign: 'center' }}>
          <Typography variant="h5" gutterBottom>📟 No hay dispositivos</Typography>
          <Typography variant="body2" color="textSecondary" sx={{ mb: 3 }}>
            Conecta tu ESP8266 y se registrará automáticamente.
          </Typography>
          <Typography variant="caption" color="textSecondary">
            El ESP debe estar conectado a la misma red WiFi y tener el código cargado.
          </Typography>
        </Card>
      </Container>
    );
  }

  const levelPercentage = selectedDevice?.currentStatus?.level || 0;
  const pumpStatus = selectedDevice?.currentStatus?.pumpStatus || false;
  const currentMin = selectedDevice?.minLevel || 20;
  const currentMax = selectedDevice?.maxLevel || 80;

  const chartData = history.slice(-20).map(item => ({
    time: new Date(item.timestamp).toLocaleTimeString(),
    level: item.level
  }));

  const avgLevel = history.length ? (history.reduce((sum, h) => sum + h.level, 0) / history.length).toFixed(0) : 0;

  return (
    <Box sx={{ display: 'flex', minHeight: '100vh', bgcolor: COLORS.light }}>
      <AppBar position="fixed" sx={{ zIndex: 1201 }}>
        <Toolbar>
          <IconButton color="inherit" edge="start" onClick={() => setDrawerOpen(true)} sx={{ mr: 2 }}>
            <MenuIcon />
          </IconButton>
          <Typography variant="h6" sx={{ flexGrow: 1 }}>
            💧 Control de Tanque
          </Typography>
          <Box display="flex" alignItems="center" gap={1}>
            <Chip label={user?.username} size="small" />
            <IconButton color="inherit" onClick={logout}>
              <LogoutIcon />
            </IconButton>
          </Box>
        </Toolbar>
      </AppBar>

      <Drawer open={drawerOpen} onClose={() => setDrawerOpen(false)}>
        <Box sx={{ width: 280, mt: 8 }}>
          <List>
            <ListItem>
              <ListItemIcon><DashboardIcon /></ListItemIcon>
              <ListItemText primary="Dashboard" />
            </ListItem>
            <ListItem button onClick={() => {
              setShowConfig(true);
              setConfigCompleted(false);
              setActiveStep(0);
              setTankHeight(selectedDevice?.tankHeight?.toString() || '100');
              setMinLevel(selectedDevice?.minLevel?.toString() || '20');
              setMaxLevel(selectedDevice?.maxLevel?.toString() || '80');
              setDrawerOpen(false);
            }}>
              <ListItemIcon><SettingsIcon /></ListItemIcon>
              <ListItemText primary="Configurar Tanque" />
            </ListItem>
          </List>
          <Divider />
          <ListItem>
            <ListItemIcon><DeviceHubIcon /></ListItemIcon>
            <ListItemText primary="Mis Dispositivos" />
          </ListItem>
          {devices.map(device => (
            <ListItem
              key={device.deviceId}
              button
              selected={selectedDevice?.deviceId === device.deviceId}
              onClick={() => {
                setSelectedDevice(device);
                setDrawerOpen(false);
              }}
              sx={{ pl: 4 }}
            >
              <ListItemText primary={device.name} secondary={device.deviceId} />
            </ListItem>
          ))}
        </Box>
      </Drawer>

      <Box component="main" sx={{ flexGrow: 1, p: 3, mt: 8 }}>
        {alert && <Alert severity={alert.type} sx={{ mb: 2 }} onClose={() => setAlert(null)}>{alert.message}</Alert>}

        <Grid container spacing={3}>
          <Grid item xs={12} md={6}>
            <Card sx={{ p: 3 }}>
              <Typography variant="subtitle2" color="textSecondary" gutterBottom>
                📊 Nivel Actual - {selectedDevice.name}
              </Typography>
              <Typography variant="h2" fontWeight="bold" color={COLORS.primary} sx={{ my: 2 }}>
                {Math.round(levelPercentage)} %
              </Typography>
              <LinearProgress variant="determinate" value={levelPercentage} sx={{ height: 12, borderRadius: 6, mb: 2 }} />
              <Box display="flex" justifyContent="space-between">
                <Typography variant="caption">Mín: {currentMin}%</Typography>
                <Typography variant="caption">Máx: {currentMax}%</Typography>
              </Box>
            </Card>
          </Grid>

          <Grid item xs={12} md={6}>
            <Card sx={{ p: 3 }}>
              <Typography variant="subtitle2" color="textSecondary" gutterBottom>
                🔌 Estado de la Bomba
              </Typography>
              <Typography variant="h3" fontWeight="bold" color={pumpStatus ? COLORS.success : COLORS.danger}>
                {pumpStatus ? 'ENCENDIDA' : 'APAGADA'}
              </Typography>
              <Typography variant="body2" color="textSecondary" sx={{ mt: 1 }}>
                {pumpStatus 
                  ? 'La bomba está funcionando. El nivel está por debajo del mínimo.'
                  : 'La bomba está detenida. El nivel está dentro del rango configurado.'}
              </Typography>
            </Card>
          </Grid>

          <Grid item xs={12} md={6}>
            <Card sx={{ p: 3 }}>
              <Typography variant="subtitle2" color="textSecondary" gutterBottom>
                📈 Estadísticas del Día
              </Typography>
              <Box textAlign="center" sx={{ mb: 2 }}>
                <Typography variant="h4" fontWeight="bold" color={COLORS.primary}>
                  {avgLevel}%
                </Typography>
                <Typography variant="caption">Promedio de nivel</Typography>
              </Box>
              <Box display="flex" justifyContent="space-around">
                <Box textAlign="center">
                  <Typography variant="h6" color={COLORS.danger}>{history.length > 0 ? Math.max(...history.map(h => h.level)) : 0}%</Typography>
                  <Typography variant="caption">Máximo</Typography>
                </Box>
                <Box textAlign="center">
                  <Typography variant="h6" color={COLORS.warning}>{history.length > 0 ? Math.min(...history.map(h => h.level)) : 0}%</Typography>
                  <Typography variant="caption">Mínimo</Typography>
                </Box>
              </Box>
            </Card>
          </Grid>

          <Grid item xs={12} md={6}>
            <Card sx={{ p: 3 }}>
              <Typography variant="subtitle2" color="textSecondary" gutterBottom>
                ⚙️ Configuración Actual
              </Typography>
              <Box display="flex" justifyContent="space-between" sx={{ mb: 1 }}>
                <Typography variant="body2">Altura del tanque:</Typography>
                <Typography variant="body2" fontWeight="bold">{selectedDevice.tankHeight || 100} cm</Typography>
              </Box>
              <Box display="flex" justifyContent="space-between" sx={{ mb: 1 }}>
                <Typography variant="body2">Nivel mínimo:</Typography>
                <Typography variant="body2" fontWeight="bold">{selectedDevice.minLevel || 20}%</Typography>
              </Box>
              <Box display="flex" justifyContent="space-between" sx={{ mb: 2 }}>
                <Typography variant="body2">Nivel máximo:</Typography>
                <Typography variant="body2" fontWeight="bold">{selectedDevice.maxLevel || 80}%</Typography>
              </Box>
              <Button 
                fullWidth 
                variant="outlined" 
                startIcon={<SettingsIcon />}
                onClick={() => {
                  setShowConfig(true);
                  setConfigCompleted(false);
                  setActiveStep(0);
                  setTankHeight(selectedDevice?.tankHeight?.toString() || '100');
                  setMinLevel(selectedDevice?.minLevel?.toString() || '20');
                  setMaxLevel(selectedDevice?.maxLevel?.toString() || '80');
                }}
              >
                Modificar Configuración
              </Button>
            </Card>
          </Grid>

          <Grid item xs={12}>
            <Card sx={{ p: 3 }}>
              <Typography variant="subtitle2" color="textSecondary" gutterBottom>
                📊 Historial de Nivel
              </Typography>
              {history.length > 0 ? (
                <ResponsiveContainer width="100%" height={300}>
                  <AreaChart data={chartData}>
                    <CartesianGrid strokeDasharray="3 3" />
                    <XAxis dataKey="time" tick={{ fontSize: 10 }} />
                    <YAxis domain={[0, 100]} unit="%" />
                    <RechartsTooltip formatter={(value) => `${Math.round(value)}%`} />
                    <Area type="monotone" dataKey="level" stroke={COLORS.primary} fill={COLORS.primary} fillOpacity={0.3} />
                  </AreaChart>
                </ResponsiveContainer>
              ) : (
                <Typography variant="body2" color="textSecondary" textAlign="center" py={4}>
                  Sin datos aún. Conecta tu ESP8266 para empezar a recibir lecturas.
                </Typography>
              )}
            </Card>
          </Grid>
        </Grid>
      </Box>
    </Box>
  );
}

export default App;